// ---- host logic: examples/api_tours/events/host.cpp ----
// API tour (C++ Wrapper): DOM events from the host. Same page, checks and case as
// examples/c/ports/kui_api_events.c (and the Go / Rust ports): on start the host registers
// listeners, dispatches synthetic events (Element::dispatchEvent) and injects real mouse and
// keyboard input (the same dispatch path as the OS), then checks what every listener saw:
// propagation order, current target, stopPropagation, flags and preventDefault, listener removal,
// mouse button and coordinates, related targets, key / code / modifiers, focus events and the
// whole drag-and-drop data API (DataTransfer). One row per check goes into #tour-log; #tour-result
// ends as "PASS n/n (known bugs: k)". Afterwards the panels react to real input.
//
// Wrapper shapes that differ from the C port (checked through the closest public method):
//   * An accessor of the wrong event kind throws kui::Error; its status() is the C status.
//   * A listener picks its view by parameter type: taking kui::MouseEvent& reads clientX / button /
//     relatedTarget of any event (relatedTarget lives on MouseEvent only, so the focus / blur
//     listeners take MouseEvent& too), taking kui::KeyboardEvent& reads key / code / modifiers.
//   * Event::dataTransfer() is nullptr outside drag events (the C status KUI_ERR_NOT_SUPPORTED);
//     DataTransfer::getData reads a missing format as "", hasData tells it apart (KUI_ERR_NOT_FOUND);
//     dragFiles() returns the list, so a single out-of-range kui_event_drag_get_file is not expressible.
//   * A missing related target reads as nullptr (KUI_ERR_NOT_FOUND).

#include <cmath>
#include <cstdio>
#include <functional>
#include <sstream>
#include <vector>

namespace {

kui::Document* g_doc = nullptr;

// ---- Self-check bookkeeping: count, log one <tr> per check, publish the verdict ----------
// check():  a documented behaviour; a failure makes the tour FAIL.
// known():  a documented behaviour the engine currently gets wrong (reported bug). A failure is
//           logged as "KNOWN BUG" and kept out of the verdict; once it passes it counts as ok.

int g_total = 0;
int g_failed = 0;
int g_known = 0;
std::string g_failed_names;

template <typename... Parts>
std::string cat(const Parts&... parts) {
    std::ostringstream out;
    out.setf(std::ios::fixed);
    out.precision(1);
    (out << ... << parts);
    return out.str();
}

std::string fixed(float value, int digits) {
    char buf[32];
    std::snprintf(buf, sizeof buf, "%.*f", digits, static_cast<double>(value));
    return buf;
}

void log_row(const std::string& name, const std::string& result, const std::string& cell) {
    kui::Element* log = g_doc->getElementById("tour-log");
    if (!log) return;
    auto row = g_doc->createElement("tr");
    row->setAttribute("data-check", name);
    row->setAttribute("data-result", result);
    if (result != "ok") row->addClass("bad");
    auto first = g_doc->createElement("td");
    first->setTextContent(name);
    row->appendChild(first);
    auto second = g_doc->createElement("td");
    second->setTextContent(cell);
    row->appendChild(second);
    log->appendChild(row);
}

void check(const std::string& name, bool ok, const std::string& detail) {
    g_total++;
    if (ok) {
        log_row(name, "ok", "ok");
        return;
    }
    g_failed++;
    g_failed_names += (g_failed_names.empty() ? "" : ", ") + name;
    std::fprintf(stderr, "tour check failed: %s: %s\n", name.c_str(), detail.c_str());
    log_row(name, "fail", "FAIL: " + detail);
}

void known(const std::string& name, bool ok, const std::string& bug, const std::string& detail) {
    if (ok) {
        g_total++;
        log_row(name, "ok", "ok");
        return;
    }
    g_known++;
    std::fprintf(stderr, "tour known bug: %s: %s\n", name.c_str(), detail.c_str());
    log_row(name, "known", "KNOWN BUG: " + bug + " (" + detail + ")");
}

void finish() {
    kui::Element* result = g_doc->getElementById("tour-result");
    if (!result) return;
    std::string text = g_failed == 0 ? cat("PASS ", g_total, "/", g_total)
                                     : cat("FAIL ", g_failed, "/", g_total, ": ", g_failed_names);
    if (g_known) text += cat(" (known bugs: ", g_known, ")");
    result->setTextContent(text);
    result->setAttribute("data-total", std::to_string(g_total));
    result->setAttribute("data-failed", std::to_string(g_failed));
    result->setAttribute("data-known", std::to_string(g_known));
    result->addClass(g_failed == 0 ? "pass" : "fail");
}

// A Wrapper method that throws (kui::Error) fails its group instead of aborting the tour.
void run_group(const char* group, const std::function<void()>& body) {
    try {
        body();
    } catch (const std::exception& error) {
        check(cat(group, ".exception"), false, error.what());
    }
}

// ---- Small helpers ------------------------------------------------------------------------

bool near(float a, float b) { return std::fabs(a - b) <= 0.51f; }

kui::Element* by_id(const char* id) { return g_doc->getElementById(id); }

void append(std::string& out, const std::string& text) { out += (out.empty() ? "" : ",") + text; }

std::string id_of(const kui::Element* element) { return element ? element->id() : std::string(); }

void set_text(const char* id, const std::string& text) {
    if (kui::Element* element = by_id(id)) element->setTextContent(text);
}

void set_class(const char* id, const char* value) {
    if (kui::Element* element = by_id(id)) element->setClassName(value);
}

kui::Rect rect_of(const char* id) {
    kui::Element* element = by_id(id);
    return element ? element->boundingClientRect() : kui::Rect{};
}

// The status a Wrapper accessor reports: KUI_OK, or the kui::Error it throws.
template <typename Fn>
KuiStatus status_of(Fn&& fn) {
    try {
        fn();
        return KUI_OK;
    } catch (const kui::Error& error) {
        return error.status();
    }
}

// Dispatches a synthetic event at #id; returns "not canceled" (-1 when #id is missing).
int dispatch(const char* id, const char* name, bool bubbles, bool cancelable) {
    kui::Element* element = by_id(id);
    if (!element) return -1;
    return element->dispatchEvent(name, bubbles, cancelable) ? 1 : 0;
}

template <typename Fn>
void listen(const char* id, const char* name, Fn&& fn) {
    kui::Element* element = by_id(id);
    if (!element) {
        std::fprintf(stderr, "kui_api_events: cannot listen for %s on #%s\n", name, id);
        return;
    }
    element->addEventListener(name, std::forward<Fn>(fn));
}

// Injected real input, in viewport coordinates.
void mouse(KuiCMouseEventType type, float x, float y, KuiCMouseButton button, int clicks) {
    g_doc->dispatchMouse(type, x, y, button, 0, clicks);
}

void click_at(const char* id, KuiCMouseButton button, int clicks) {
    const kui::Rect rect = rect_of(id);
    const float x = rect.x + rect.width / 2;
    const float y = rect.y + rect.height / 2;
    mouse(KUI_C_MOUSE_MOVED, x, y, KUI_C_MOUSE_BUTTON_NONE, 0);
    mouse(KUI_C_MOUSE_PRESSED, x, y, button, clicks);
    mouse(KUI_C_MOUSE_RELEASED, x, y, button, clicks);
}

void move_to(const char* id) {
    const kui::Rect rect = rect_of(id);
    mouse(KUI_C_MOUSE_MOVED, rect.x + rect.width / 2, rect.y + rect.height / 2, KUI_C_MOUSE_BUTTON_NONE, 0);
}

void focus_id(const char* id) {
    if (kui::Element* element = by_id(id)) element->focus();
}

void blur_id(const char* id) {
    if (kui::Element* element = by_id(id)) element->blur();
}

// ---- Propagation: one listener per layer records where the event is ----------------------

std::string g_trace;    // current targets, in call order
std::string g_targets;  // targets, in call order
int g_last_bubbles = -1;  // flags read by the last listener that ran
int g_last_cancelable = -1;
int g_last_prevented = -1;

const char* const k_layers[] = {"ev-outer", "ev-middle", "ev-inner"};

void on_layer(kui::Event& event) {
    kui::Element* current = event.currentTarget();
    std::string id = id_of(current);
    append(g_trace, id.size() > 3 ? id.substr(3) : std::string("?"));  // "ev-inner" -> "inner"
    id = id_of(event.target());
    append(g_targets, id.size() > 3 ? id.substr(3) : std::string("?"));
    g_last_bubbles = event.bubbles() ? 1 : 0;
    g_last_cancelable = event.cancelable() ? 1 : 0;
    g_last_prevented = event.defaultPrevented() ? 1 : 0;
    if (current) current->addClass("hit");
}

int fire_layers(const char* id, const char* name, bool bubbles, bool cancelable) {
    g_trace.clear();
    g_targets.clear();
    g_last_bubbles = g_last_cancelable = g_last_prevented = -1;
    for (const char* layer : k_layers) {
        if (kui::Element* element = by_id(layer)) element->removeClass("hit");
    }
    return dispatch(id, name, bubbles, cancelable);
}

void bind_layers() {
    for (const char* layer : k_layers) {
        for (const char* name : {"ping", "halt", "veto"}) listen(layer, name, on_layer);
    }
    // "halt": the middle layer stops the event after its own listeners.
    listen("ev-middle", "halt", [](kui::Event& event) { event.stopPropagation(); });
    // "veto": the inner layer cancels the default action.
    listen("ev-inner", "veto", [](kui::Event& event) { event.preventDefault(); });
}

void check_propagation() {
    fire_layers("ev-inner", "ping", true, false);
    check("prop.bubble_order", g_trace == "inner,middle,outer", cat("current targets '", g_trace, "'"));
    check("prop.target", g_targets == "inner,inner,inner", cat("targets '", g_targets, "'"));

    fire_layers("ev-inner", "ping", false, false);
    check("prop.non_bubbling", g_trace == "inner" && g_last_bubbles == 0,
          cat("current targets '", g_trace, "', bubbles ", g_last_bubbles));

    fire_layers("ev-middle", "ping", true, false);
    check("prop.from_middle", g_trace == "middle,outer" && g_targets == "middle,middle",
          cat("current targets '", g_trace, "', targets '", g_targets, "'"));

    fire_layers("ev-inner", "halt", true, false);
    check("prop.stop_propagation", g_trace == "inner,middle", cat("current targets '", g_trace, "'"));

    int not_canceled = fire_layers("ev-inner", "veto", true, true);
    check("cancel.prevent_default", not_canceled == 0 && g_last_prevented == 1 && g_last_cancelable == 1 &&
          g_last_bubbles == 1 && g_trace == "inner,middle,outer",
          cat("not canceled ", not_canceled, ", flags at outer b", g_last_bubbles, " c", g_last_cancelable,
              " p", g_last_prevented, ", trace '", g_trace, "'"));

    // preventDefault on a non-cancelable event changes nothing.
    not_canceled = fire_layers("ev-inner", "veto", true, false);
    check("cancel.not_cancelable", not_canceled == 1 && g_last_prevented == 0 && g_last_cancelable == 0,
          cat("not canceled ", not_canceled, ", flags at outer c", g_last_cancelable, " p", g_last_prevented));

    // A detached element cannot be dispatched at (kui_c.h): KUI_ERR_INVALID_ARG.
    auto loose = g_doc->createElement("div");
    const KuiStatus status = status_of([&] { loose->dispatchEvent("ping", true, false); });
    known("dispatch.detached", status == KUI_ERR_INVALID_ARG,
          "dispatch_event on an element that is not in the document returns KUI_OK",
          cat("status ", static_cast<int>(status)));
}

// ---- Listener management: ids, removing one, removing all of one name --------------------

std::string g_tick_trace;
std::vector<kui::u32> g_tick_ids;
int g_tick_serial = 0;

kui::u32 add_tick() {
    kui::Element* target = by_id("lm-target");
    const int serial = ++g_tick_serial;
    if (!target) return 0;
    return target->addEventListener("tick", [serial] { append(g_tick_trace, std::to_string(serial)); });
}

KuiStatus remove_tick(kui::u32 id) {
    kui::Element* target = by_id("lm-target");
    if (!target) return KUI_ERR_NOT_FOUND;
    return status_of([&] { target->removeEventListener("tick", id); });
}

KuiStatus remove_all(const char* name) {
    kui::Element* target = by_id("lm-target");
    if (!target) return KUI_ERR_NOT_FOUND;
    return status_of([&] { target->removeEventListeners(name); });
}

void fire_tick(const char* name) {
    g_tick_trace.clear();
    dispatch("lm-target", name, false, false);
}

void check_listeners() {
    const kui::u32 first = add_tick();
    const kui::u32 second = add_tick();
    const kui::u32 third = add_tick();

    fire_tick("tick");
    check("listen.registration_order", g_tick_trace == "1,2,3" && first && second && third && first != second &&
          second != third, cat("ran '", g_tick_trace, "', ids ", first, " ", second, " ", third));

    KuiStatus status = remove_tick(second);
    fire_tick("tick");
    check("listen.remove_event_listener", status == KUI_OK && g_tick_trace == "1,3",
          cat("status ", static_cast<int>(status), ", ran '", g_tick_trace, "'"));

    listen("lm-target", "tock", [] { append(g_tick_trace, "tock"); });
    status = remove_all("tick");
    fire_tick("tick");
    check("listen.remove_event_listeners", status == KUI_OK && g_tick_trace.empty(),
          cat("status ", static_cast<int>(status), ", ran '", g_tick_trace, "'"));
    fire_tick("tock");
    check("listen.remove_keeps_other_names", g_tick_trace == "tock", cat("ran '", g_tick_trace, "'"));
    remove_all("tock");
    g_tick_serial = 0;
}

// ---- Event object: a synthetic event and the accessors of the other kinds ----------------

struct ProbeResult {
    std::string type;
    int tag = -1;
    int bubbles = -1, cancelable = -1, prevented = -1;
    bool related = true;  // a related target was found
    KuiStatus mouse_xy = KUI_OK, mouse_button = KUI_OK, key = KUI_OK, code = KUI_OK, modifiers = KUI_OK;
    bool drag_data = true;  // Event::dataTransfer() returned an object
    KuiStatus drag_files = KUI_OK;
};

ProbeResult g_probe;

void bind_probe() {
    // The base view: type, tag, flags and the drag data.
    listen("probe", "probe", [](kui::Event& event) {
        g_probe = ProbeResult{};
        g_probe.type = event.type();
        g_probe.tag = static_cast<int>(event.typeTag());
        g_probe.bubbles = event.bubbles() ? 1 : 0;
        g_probe.cancelable = event.cancelable() ? 1 : 0;
        g_probe.prevented = event.defaultPrevented() ? 1 : 0;
        g_probe.drag_data = event.dataTransfer() != nullptr;
        g_probe.drag_files = status_of([&] { event.dragFiles(); });
    });
    // The mouse view of the same event: related target, coordinates and button.
    listen("probe", "probe", [](kui::MouseEvent& event) {
        g_probe.related = event.relatedTarget() != nullptr;
        g_probe.mouse_xy = status_of([&] { event.clientX(); });
        g_probe.mouse_button = status_of([&] { event.button(); });
    });
    // The keyboard view: key, code and modifiers.
    listen("probe", "probe", [](kui::KeyboardEvent& event) {
        g_probe.key = status_of([&] { event.key(); });
        g_probe.code = status_of([&] { event.code(); });
        g_probe.modifiers = status_of([&] { event.ctrlKey(); });
    });
}

void check_probe() {
    const ProbeResult& p = g_probe;
    dispatch("probe", "probe", true, false);
    check("event.type", p.type == "probe" && p.tag == static_cast<int>(kui::EventTypeTag::Base),
          cat("type '", p.type, "', tag ", p.tag));
    check("event.flags", p.bubbles == 1 && p.cancelable == 0 && p.prevented == 0,
          cat("bubbles ", p.bubbles, " cancelable ", p.cancelable, " prevented ", p.prevented));
    check("event.no_related_target", !p.related, "a related target was returned");
    check("event.mouse_not_supported", p.mouse_xy == KUI_ERR_NOT_SUPPORTED && p.mouse_button == KUI_ERR_NOT_SUPPORTED,
          cat("client ", static_cast<int>(p.mouse_xy), ", button ", static_cast<int>(p.mouse_button)));
    check("event.key_not_supported", p.key == KUI_ERR_NOT_SUPPORTED && p.code == KUI_ERR_NOT_SUPPORTED &&
          p.modifiers == KUI_ERR_NOT_SUPPORTED,
          cat("key ", static_cast<int>(p.key), ", code ", static_cast<int>(p.code), ", modifiers ",
              static_cast<int>(p.modifiers)));
    check("event.drag_not_supported", !p.drag_data && p.drag_files == KUI_ERR_NOT_SUPPORTED,
          cat("dataTransfer ", p.drag_data ? "present" : "null", ", files ", static_cast<int>(p.drag_files)));
}

// ---- Mouse: button, three coordinate spaces, related targets -----------------------------

struct MouseRecord {
    int seen = 0;
    int button = -1;
    int tag = -1;
    float cx = 0, cy = 0, ox = 0, oy = 0, px = 0, py = 0;
    int bubbles = -1, cancelable = -1, prevented = -1;
};

MouseRecord g_click, g_down, g_dbl, g_ctx;

void write_mouse_line(const std::string& type, const MouseRecord& r) {
    kui::Element* out = by_id("mouse-last");
    if (!out) return;
    out->setTextContent(cat(type, " button=", r.button, " client=", fixed(r.cx, 0), ",", fixed(r.cy, 0),
                            " offset=", fixed(r.ox, 0), ",", fixed(r.oy, 0), " page=", fixed(r.px, 0), ",",
                            fixed(r.py, 0)));
    out->setAttribute("data-type", type);
    out->setAttribute("data-button", std::to_string(r.button));
    out->setAttribute("data-cx", fixed(r.cx, 2));
    out->setAttribute("data-cy", fixed(r.cy, 2));
    out->setAttribute("data-ox", fixed(r.ox, 2));
    out->setAttribute("data-oy", fixed(r.oy, 2));
    out->setAttribute("data-px", fixed(r.px, 2));
    out->setAttribute("data-py", fixed(r.py, 2));
}

void on_mouse(kui::MouseEvent& event, MouseRecord& r) {
    const std::string type = event.type();
    // The pad keeps its own context menu: cancel the default one.
    if (type == "contextmenu") event.preventDefault();
    r.seen++;
    r.button = event.button();
    r.tag = static_cast<int>(event.typeTag());
    r.cx = event.clientX();
    r.cy = event.clientY();
    r.ox = event.offsetX();
    r.oy = event.offsetY();
    r.px = event.pageX();
    r.py = event.pageY();
    r.bubbles = event.bubbles() ? 1 : 0;
    r.cancelable = event.cancelable() ? 1 : 0;
    r.prevented = event.defaultPrevented() ? 1 : 0;
    if (type != "mousedown") write_mouse_line(type, r);
}

std::string g_enter;
std::string g_leave;
int g_enter_bubbles = -1;

void on_hover(kui::MouseEvent& event) {
    const std::string type = event.type();
    kui::Element* current = event.currentTarget();
    const std::string related = id_of(event.relatedTarget());
    if (type == "mouseenter") {
        g_enter = cat("#", id_of(current), " from #", related.empty() ? std::string("-") : related);
        g_enter_bubbles = event.bubbles() ? 1 : 0;
    } else {
        g_leave = cat("#", id_of(current), " to #", related.empty() ? std::string("-") : related);
    }
    if (current) {
        if (type == "mouseenter") current->addClass("in");
        else current->removeClass("in");
    }
    set_text("hover-out", cat("enter: ", g_enter.empty() ? std::string("-") : g_enter, " | leave: ",
                              g_leave.empty() ? std::string("-") : g_leave));
}

// ---- Capture phase: listeners registered with capture = true run while the event travels down ----

void check_capture() {
    kui::Element* outer = by_id("ev-outer");
    kui::Element* middle = by_id("ev-middle");
    kui::Element* inner = by_id("ev-inner");
    if (!outer || !middle || !inner) {
        check("capture.setup", false, "missing the propagation layers");
        return;
    }
    std::string order;
    auto tag = [&order](const char* name) {
        return [&order, name](kui::Event&) {
            order += name;
            order += ' ';
        };
    };
    const auto outer_plain = outer->addEventListener("capture-probe", tag("op"));
    const auto middle_plain = middle->addEventListener("capture-probe", tag("mp"));
    const auto inner_plain = inner->addEventListener("capture-probe", tag("ip"));
    const auto inner_capture = inner->addEventListener("capture-probe", tag("ic"), true);
    const auto outer_capture = outer->addEventListener("capture-probe", tag("oc"), true);
    inner->dispatchEvent("capture-probe", true, false);
    check("capture.order", order == "oc ic ip mp op ", cat("order '", order, "'"));

    outer->removeEventListener("capture-probe", outer_capture);
    order.clear();
    inner->dispatchEvent("capture-probe", true, false);
    check("capture.remove", order == "ic ip mp op ", cat("order '", order, "'"));

    outer->removeEventListener("capture-probe", outer_plain);
    middle->removeEventListener("capture-probe", middle_plain);
    inner->removeEventListener("capture-probe", inner_plain);
    inner->removeEventListener("capture-probe", inner_capture);
}

void bind_mouse() {
    if (kui::Element* pad = by_id("mouse-pad")) {
        const struct { const char* name; MouseRecord* record; } kinds[] = {
            {"click", &g_click}, {"mousedown", &g_down}, {"dblclick", &g_dbl}, {"contextmenu", &g_ctx}};
        for (const auto& kind : kinds) {
            MouseRecord* record = kind.record;
            pad->addEventListener(kind.name, [record](kui::MouseEvent& event) { on_mouse(event, *record); });
        }
    }
    for (const char* id : {"hover-a", "hover-b"}) {
        listen(id, "mouseenter", on_hover);
        listen(id, "mouseleave", on_hover);
    }
}

// ---- Wheel: the scroll amount of an injected wheel event --------------------------------------

void check_wheel() {
    kui::Element* pad = by_id("mouse-pad");
    if (!pad) {
        check("wheel.setup", false, "missing #mouse-pad");
        return;
    }
    const kui::Rect rect = rect_of("mouse-pad");
    const float x = rect.x + rect.width / 2;
    const float y = rect.y + rect.height / 2;
    float dx = -1.0f, dy = -1.0f;
    int seen = 0;
    std::string error;
    const auto wheel_id = pad->addEventListener("wheel", [&](kui::WheelEvent& event) {
        ++seen;
        try {
            dx = event.deltaX();
            dy = event.deltaY();
        } catch (const kui::Error& thrown) {
            error = thrown.what();
        }
    });
    g_doc->dispatchMouse(KUI_C_MOUSE_WHEEL, x, y, KUI_C_MOUSE_BUTTON_NONE, 0, 0, 3.0f, -7.5f);
    pad->removeEventListener("wheel", wheel_id);
    check("wheel.delta", seen == 1 && error.empty() && near(dx, 3.0f) && near(dy, -7.5f),
          cat("seen ", seen, ", delta ", dx, ",", dy, ", error '", error, "'"));

    // Only a wheel event has a scroll amount.
    KuiStatus not_wheel = KUI_OK;
    const auto probe_id = pad->addEventListener("wheel-probe", [&](kui::WheelEvent& event) {
        try {
            (void)event.deltaX();
        } catch (const kui::Error& thrown) {
            not_wheel = thrown.status();
        }
    });
    pad->dispatchEvent("wheel-probe", false, false);
    pad->removeEventListener("wheel-probe", probe_id);
    check("wheel.delta_of_a_non_wheel_event", not_wheel == KUI_ERR_NOT_SUPPORTED, cat("status ", static_cast<int>(not_wheel)));
}

void check_mouse() {
    const kui::Rect pad = rect_of("mouse-pad");
    const float cx = pad.x + pad.width / 2;
    const float cy = pad.y + pad.height / 2;
    kui::Element* root = g_doc->documentElement();
    const float scroll_top = root ? root->scrollTop() : 0.0f;

    click_at("mouse-pad", KUI_C_MOUSE_BUTTON_LEFT, 1);
    check("mouse.click", g_click.seen == 1 && g_click.button == KUI_C_MOUSE_BUTTON_LEFT &&
          g_click.tag == static_cast<int>(kui::EventTypeTag::Mouse) && g_click.bubbles == 1 && g_click.cancelable == 1,
          cat("seen ", g_click.seen, ", button ", g_click.button, ", tag ", g_click.tag, ", bubbles ", g_click.bubbles,
              " cancelable ", g_click.cancelable));
    check("mouse.client_xy", near(g_click.cx, cx) && near(g_click.cy, cy),
          cat("client ", g_click.cx, ",", g_click.cy, ", pad centre ", cx, ",", cy));
    // Offset coordinates are relative to the padding box: inside the 4px border.
    known("mouse.offset_xy", near(g_click.ox, cx - pad.x - 4) && near(g_click.oy, cy - pad.y - 4),
          "mouse events never get offset coordinates (always 0,0)",
          cat("offset ", g_click.ox, ",", g_click.oy, ", want ", cx - pad.x - 4, ",", cy - pad.y - 4));
    known("mouse.page_xy", near(g_click.px, g_click.cx) && near(g_click.py, g_click.cy + scroll_top),
          "mouse events never get page coordinates (always 0,0)",
          cat("page ", g_click.px, ",", g_click.py, ", client ", g_click.cx, ",", g_click.cy, ", document scroll ",
              scroll_top));

    click_at("mouse-pad", KUI_C_MOUSE_BUTTON_RIGHT, 1);
    check("mouse.right_button", g_down.button == KUI_C_MOUSE_BUTTON_RIGHT && g_ctx.seen == 1 &&
          g_ctx.button == KUI_C_MOUSE_BUTTON_RIGHT && g_ctx.prevented == 1,
          cat("mousedown button ", g_down.button, ", contextmenu seen ", g_ctx.seen, " button ", g_ctx.button,
              " prevented ", g_ctx.prevented));

    // kui_c.h: click_count 2 injects the second click of a double-click.
    click_at("mouse-pad", KUI_C_MOUSE_BUTTON_LEFT, 2);
    known("mouse.injected_click_count", g_dbl.seen == 1,
          "kui_devtools_dispatch_mouse_event ignores click_count (counts clicks by timing)",
          cat("dblclick seen ", g_dbl.seen));
    // Two clicks in a row on the same spot make a double-click.
    g_dbl.seen = 0;
    click_at("mouse-pad", KUI_C_MOUSE_BUTTON_LEFT, 1);
    click_at("mouse-pad", KUI_C_MOUSE_BUTTON_LEFT, 2);
    check("mouse.dblclick", g_dbl.seen == 1 && g_dbl.button == KUI_C_MOUSE_BUTTON_LEFT,
          cat("dblclick seen ", g_dbl.seen, " button ", g_dbl.button));

    move_to("hover-a");
    move_to("hover-b");
    check("mouse.related_target", g_leave == "#hover-a to #hover-b" && g_enter == "#hover-b from #hover-a",
          cat("leave '", g_leave, "', enter '", g_enter, "'"));
    // UI Events: mouseenter / mouseleave do not bubble.
    known("mouse.enter_does_not_bubble", g_enter_bubbles == 0,
          "mouseenter / mouseleave are dispatched as bubbling events", cat("bubbles ", g_enter_bubbles));
    move_to("probe");
}

// ---- Keyboard and focus ------------------------------------------------------------------

struct KeyRecord {
    int seen = 0;
    std::string key, code;
    int ctrl = -1, shift = -1, alt = -1, meta = -1;
    int tag = -1;
    KuiStatus mouse = KUI_OK;
};

KeyRecord g_key;
std::string g_blur_line;
std::string g_focus_line;
int g_focus_tag = -1;

void on_key(kui::KeyboardEvent& event) {
    g_key = KeyRecord{};
    g_key.seen = 1;
    g_key.key = event.key();
    g_key.code = event.code();
    g_key.ctrl = event.ctrlKey() ? 1 : 0;
    g_key.shift = event.shiftKey() ? 1 : 0;
    g_key.alt = event.altKey() ? 1 : 0;
    g_key.meta = event.metaKey() ? 1 : 0;
    g_key.tag = static_cast<int>(event.typeTag());
    std::string mods;
    if (g_key.ctrl) append(mods, "ctrl");
    if (g_key.shift) append(mods, "shift");
    if (g_key.alt) append(mods, "alt");
    if (g_key.meta) append(mods, "meta");
    set_text("key-out", cat("keydown key=", g_key.key, " code=", g_key.code, " mods=",
                            mods.empty() ? std::string("none") : mods));
}

// The focus / blur listeners take the MouseEvent view: relatedTarget lives there in the Wrapper.
void on_focus_change(kui::MouseEvent& event) {
    const std::string type = event.type();
    const std::string current = id_of(event.currentTarget());
    const std::string related = id_of(event.relatedTarget());
    g_focus_tag = static_cast<int>(event.typeTag());
    if (type == "blur") {
        g_blur_line = cat("blur #", current, " to #", related.empty() ? std::string("-") : related);
        set_text("focus-out", g_blur_line);
    } else {
        g_focus_line = cat("focus #", current, " from #", related.empty() ? std::string("-") : related);
        set_text("focus-out", g_focus_line);
    }
}

void bind_keyboard() {
    listen("key-pad", "keydown", on_key);
    // The mouse view of the same keydown: its accessors must refuse a keyboard event.
    listen("key-pad", "keydown", [](kui::MouseEvent& event) {
        g_key.mouse = status_of([&] { event.clientX(); });
    });
    listen("key-pad", "focus", on_focus_change);
    listen("key-pad", "blur", on_focus_change);
    listen("key-other", "focus", on_focus_change);
}

void check_keyboard() {
    focus_id("key-pad");
    // Ctrl (2) + Shift (8), the DevTools modifier bits.
    g_doc->dispatchKey(KUI_C_KEY_DOWN, "a", "KeyA", 2 | 8);
    g_doc->dispatchKey(KUI_C_KEY_UP, "a", "KeyA", 2 | 8);
    check("key.key_code", g_key.seen && g_key.key == "a" && g_key.code == "KeyA",
          cat("seen ", g_key.seen, " key '", g_key.key, "' code '", g_key.code, "'"));
    check("key.modifiers", g_key.ctrl == 1 && g_key.shift == 1 && g_key.alt == 0 && g_key.meta == 0,
          cat("ctrl ", g_key.ctrl, " shift ", g_key.shift, " alt ", g_key.alt, " meta ", g_key.meta));
    check("key.type_tag", g_key.tag == static_cast<int>(kui::EventTypeTag::Keyboard) &&
          g_key.mouse == KUI_ERR_NOT_SUPPORTED,
          cat("tag ", g_key.tag, ", mouse accessor status ", static_cast<int>(g_key.mouse)));

    focus_id("key-other");
    check("focus.blur_related_target", g_blur_line == "blur #key-pad to #key-other", cat("'", g_blur_line, "'"));
    check("focus.focus_related_target", g_focus_line == "focus #key-other from #key-pad" &&
          g_focus_tag == static_cast<int>(kui::EventTypeTag::Focus), cat("'", g_focus_line, "', tag ", g_focus_tag));
    blur_id("key-other");
}

// ---- Drag and drop: the DataTransfer API from dragstart to dragend -----------------------

struct DragRecord {
    std::string seq;  // event types, repeats folded
    std::string last;
    std::size_t start_types = 0;  // after set x3 + clear x1 in dragstart
    std::string start_list;
    std::string start_read;
    int start_allowed = -1;
    int over_effect = -1;
    int drops = 0;
    std::string drop_plain;
    std::string drop_custom;
    bool drop_junk = true;  // hasData("text/x-junk")
    std::size_t drop_types = 0;
    std::size_t drop_files = 0;
    std::size_t transfer_files = 0;
    int drop_allowed = -1;
    int drop_effect = -1;
    int drop_tag = -1;
    float drop_x = 0, drop_y = 0;
    std::size_t cleared_types = 99;
    int end_effect = -1;
};

DragRecord g_drag;

const char* effect_name(kui::DropEffect effect) {
    switch (effect) {
        case kui::DropEffect::Copy: return "copy";
        case kui::DropEffect::Move: return "move";
        case kui::DropEffect::Link: return "link";
        default: return "none";
    }
}

const char* allowed_name(kui::EffectAllowed effect) {
    switch (effect) {
        case kui::EffectAllowed::None: return "none";
        case kui::EffectAllowed::Copy: return "copy";
        case kui::EffectAllowed::Move: return "move";
        case kui::EffectAllowed::Link: return "link";
        case kui::EffectAllowed::CopyMove: return "copyMove";
        case kui::EffectAllowed::CopyLink: return "copyLink";
        case kui::EffectAllowed::MoveLink: return "moveLink";
        case kui::EffectAllowed::All: return "all";
        default: return "uninitialized";
    }
}

void note_drag(const std::string& type) {
    if (type == g_drag.last) return;
    g_drag.last = type;
    g_drag.seq += (g_drag.seq.empty() ? "" : " > ") + type;
    set_text("drag-seq", g_drag.seq);
}

void on_drag_source(kui::Event& event) {
    const std::string type = event.type();
    kui::DataTransfer* data = event.dataTransfer();
    if (type == "dragstart" && data) {
        g_drag = DragRecord{};
        set_class("drop-zone", "");
        set_text("drop-out", "dragging...");
        data->setEffectAllowed(kui::EffectAllowed::CopyMove);
        data->setData("text/plain", "kui-chip");
        data->setData("text/x-kui", "42");
        data->setData("text/x-junk", "scratch");
        data->clearData("text/x-junk");
        const std::vector<std::string>& types = data->types();
        g_drag.start_types = types.size();
        for (const auto& item : types) append(g_drag.start_list, item);
        g_drag.start_read = data->getData("text/plain");
        g_drag.start_allowed = static_cast<int>(data->effectAllowed());
    } else if (type == "dragend" && data) {
        g_drag.end_effect = static_cast<int>(data->dropEffect());
    }
    note_drag(type);
}

void on_drop_zone(kui::Event& event) {
    const std::string type = event.type();
    note_drag(type);
    kui::DataTransfer* data = event.dataTransfer();
    if (!data) return;
    if (type == "dragenter" || type == "dragover") {
        // Accept the drop and ask for a copy.
        event.preventDefault();
        data->setDropEffect(kui::DropEffect::Copy);
        g_drag.over_effect = static_cast<int>(data->dropEffect());
        set_class("drop-zone", "over");
        return;
    }
    if (type == "dragleave") {
        if (!g_drag.drops) set_class("drop-zone", "");
        return;
    }
    // drop
    event.preventDefault();
    g_drag.drops++;
    g_drag.drop_plain = data->getData("text/plain");
    g_drag.drop_custom = data->getData("text/x-kui");
    g_drag.drop_junk = data->hasData("text/x-junk");
    g_drag.drop_types = data->types().size();
    const std::vector<std::string> files = event.dragFiles();
    g_drag.drop_files = files.size();
    g_drag.transfer_files = data->files().size();
    std::string file_list;
    for (const auto& path : files) append(file_list, path);
    g_drag.drop_allowed = static_cast<int>(data->effectAllowed());
    g_drag.drop_effect = static_cast<int>(data->dropEffect());
    g_drag.drop_tag = static_cast<int>(event.typeTag());
    if (auto* mouse_event = dynamic_cast<kui::MouseEvent*>(&event)) {
        g_drag.drop_x = mouse_event->clientX();
        g_drag.drop_y = mouse_event->clientY();
    }
    // Done with the data: clear every format.
    data->clearData();
    g_drag.cleared_types = data->types().size();

    set_text("drop-out", cat("dropped '", g_drag.drop_plain, "' + '", g_drag.drop_custom, "' | types ",
                             g_drag.drop_types, " | files ", g_drag.drop_files, file_list.empty() ? "" : ": ",
                             file_list, " | effect ", effect_name(static_cast<kui::DropEffect>(g_drag.drop_effect)),
                             " / allowed ", allowed_name(static_cast<kui::EffectAllowed>(g_drag.drop_allowed))));
    set_class("drop-zone", "dropped");
}

void bind_drag() {
    listen("drag-src", "dragstart", on_drag_source);
    listen("drag-src", "dragend", on_drag_source);
    for (const char* name : {"dragenter", "dragover", "dragleave", "drop"}) listen("drop-zone", name, on_drop_zone);
}

// Press on the chip, move past the drag threshold, move onto the zone and release.
void simulate_drag() {
    const kui::Rect src = rect_of("drag-src");
    const kui::Rect zone = rect_of("drop-zone");
    const float sx = src.x + src.width / 2;
    const float sy = src.y + src.height / 2;
    const float zx = zone.x + zone.width / 2;
    const float zy = zone.y + zone.height / 2;
    mouse(KUI_C_MOUSE_MOVED, sx, sy, KUI_C_MOUSE_BUTTON_NONE, 0);
    mouse(KUI_C_MOUSE_PRESSED, sx, sy, KUI_C_MOUSE_BUTTON_LEFT, 1);
    mouse(KUI_C_MOUSE_MOVED, sx + 12, sy, KUI_C_MOUSE_BUTTON_LEFT, 0);
    mouse(KUI_C_MOUSE_MOVED, zx, zy, KUI_C_MOUSE_BUTTON_LEFT, 0);
    mouse(KUI_C_MOUSE_RELEASED, zx, zy, KUI_C_MOUSE_BUTTON_LEFT, 1);
}

bool has(const std::string& text, const char* part) { return text.find(part) != std::string::npos; }

void check_drag() {
    const kui::Rect zone = rect_of("drop-zone");
    const DragRecord& d = g_drag;
    simulate_drag();
    check("drag.sequence", d.seq.rfind("dragstart", 0) == 0 && has(d.seq, "dragenter > dragover") &&
          has(d.seq, "drop") && has(d.seq, "dragend"), cat("sequence '", d.seq, "'"));
    check("drag.set_clear_types", d.start_types == 2 && d.start_list == "text/plain,text/x-kui" &&
          d.start_read == "kui-chip",
          cat("types ", d.start_types, " '", d.start_list, "', read back '", d.start_read, "'"));
    check("drag.effect_allowed", d.start_allowed == static_cast<int>(kui::EffectAllowed::CopyMove) &&
          d.drop_allowed == static_cast<int>(kui::EffectAllowed::CopyMove),
          cat("dragstart ", d.start_allowed, ", drop ", d.drop_allowed));
    check("drag.drop_effect", d.over_effect == static_cast<int>(kui::DropEffect::Copy) &&
          d.drop_effect == static_cast<int>(kui::DropEffect::Copy),
          cat("dragover ", d.over_effect, ", drop ", d.drop_effect));
    check("drag.get_data", d.drops == 1 && d.drop_plain == "kui-chip" && d.drop_custom == "42" && !d.drop_junk &&
          d.drop_types == 2,
          cat("drops ", d.drops, ", plain '", d.drop_plain, "', custom '", d.drop_custom, "', cleared format present ",
              d.drop_junk, ", types ", d.drop_types));
    // An in-page drag carries no files.
    check("drag.files", d.drop_files == 0 && d.transfer_files == 0,
          cat("files ", d.drop_files, ", DataTransfer::files ", d.transfer_files));
    check("drag.clear_all", d.cleared_types == 0, cat("types after clear ", d.cleared_types));
    check("drag.drop_event", d.drop_tag == static_cast<int>(kui::EventTypeTag::Drag) &&
          near(d.drop_x, zone.x + zone.width / 2) && near(d.drop_y, zone.y + zone.height / 2),
          cat("tag ", d.drop_tag, ", client ", d.drop_x, ",", d.drop_y));
    // HTML DnD: dragend's dropEffect is the operation the drop target chose (copy).
    known("drag.dragend_effect", d.end_effect == static_cast<int>(kui::DropEffect::Copy),
          "dragend reports dropEffect 'move' whatever the target chose", cat("dragend effect ", d.end_effect));
    move_to("probe");
}

// ---- Panel buttons -----------------------------------------------------------------------

void show_prop(const char* name, int not_canceled) {
    set_text("prop-out", cat(name, ": ", g_trace.empty() ? std::string("-") : g_trace, " | bubbles=", g_last_bubbles,
                             " cancelable=", g_last_cancelable, " prevented=", g_last_prevented,
                             " not_canceled=", not_canceled));
}

void show_listeners(const std::string& note) {
    set_text("lm-out", cat("listeners=", g_tick_ids.size(), note.empty() ? "" : " | ", note));
}

void on_lm_add() {
    if (g_tick_ids.size() < 32) g_tick_ids.push_back(add_tick());
    show_listeners("");
}

void on_lm_remove() {
    if (!g_tick_ids.empty()) {
        remove_tick(g_tick_ids.back());
        g_tick_ids.pop_back();
    }
    show_listeners("");
}

void on_lm_clear() {
    remove_all("tick");
    g_tick_ids.clear();
    g_tick_serial = 0;
    show_listeners("");
}

void on_lm_fire() {
    fire_tick("tick");
    set_class("lm-target", g_tick_trace.empty() ? "" : "fired");
    show_listeners(cat("ran: ", g_tick_trace.empty() ? std::string("none") : g_tick_trace));
}

void on_probe_button() {
    static const char* const tags[] = {"base", "mouse", "wheel", "pointer", "keyboard", "focus", "input", "drag"};
    const ProbeResult& p = g_probe;
    dispatch("probe", "probe", true, false);
    set_text("probe-out", cat("type=", p.type, " tag=", (p.tag >= 0 && p.tag < 8) ? tags[p.tag] : "?",
                              " bubbles=", p.bubbles, " cancelable=", p.cancelable,
                              " | related=", p.related ? "?" : "none",
                              " mouse=", p.mouse_xy == KUI_ERR_NOT_SUPPORTED ? "n/a" : "?",
                              " key=", p.key == KUI_ERR_NOT_SUPPORTED ? "n/a" : "?",
                              " drag=", !p.drag_data ? "n/a" : "?"));
}

// The injected drag must not run inside this click's own dispatch: start it from a timer.
void on_dnd_simulate() {
    set_text("drag-seq", "-");
    set_text("drop-out", "-");
    kui::Platform::setTimeout([] { simulate_drag(); }, 10);
}

// Clicks on #id run `handler` (a missing button is reported as a failed check).
void on_click(const char* id, void (*handler)()) {
    kui::Element* button = by_id(id);
    if (!button) {
        check(cat("ui.", id), false, "button missing");
        return;
    }
    button->addEventListener("click", [handler](kui::Event&) { handler(); });
}

}  // namespace

void tour_ready(kui::Window& window, kui::Document& document) {
    (void)window;
    g_doc = &document;

    bind_layers();
    bind_probe();
    bind_mouse();
    bind_keyboard();
    bind_drag();

    run_group("prop", check_propagation);
    run_group("listen", check_listeners);
    run_group("event", check_probe);
    run_group("mouse", check_mouse);
    run_group("key", check_keyboard);
    run_group("drag", check_drag);
    run_group("wheel", check_wheel);
    run_group("capture", check_capture);
    finish();

    on_click("btn-prop-bubble", [] { show_prop("ping", fire_layers("ev-inner", "ping", true, false)); });
    on_click("btn-prop-flat", [] { show_prop("ping (no bubbles)", fire_layers("ev-inner", "ping", false, false)); });
    on_click("btn-prop-stop", [] { show_prop("halt", fire_layers("ev-inner", "halt", true, false)); });
    on_click("btn-prop-cancel", [] { show_prop("veto", fire_layers("ev-inner", "veto", true, true)); });
    on_click("btn-lm-add", on_lm_add);
    on_click("btn-lm-remove", on_lm_remove);
    on_click("btn-lm-clear", on_lm_clear);
    on_click("btn-lm-fire", on_lm_fire);
    on_click("btn-probe", on_probe_button);
    on_click("btn-dnd-simulate", on_dnd_simulate);
}
// ---- end of examples/api_tours/events/host.cpp ----

int main() {
    try {
        if (!kui::Platform::init()) return 3;
        kui::WindowConfig config;
        config.title = "KUI API \xe2\x80\x94 events";
        config.width = 1100;
        config.height = 780;
        auto window = kui::Window::create(config);
        if (!window) return 4;
        kui::Document* document = window->document();
        auto script = kui::ScriptEngine::create();
        if (script) {
            script->setErrorHandler([](const std::string& error, const std::string& source, int line) {
                std::fprintf(stderr, "[Lua] %s:%d: %s\n", source.c_str(), line, error.c_str());
            });
            script->bindDocument(document);
            window->setScriptEngine(script.get());
        }
        tour_script = script.get();
        document->loadHTML(k_tour_page);
        if (script) script->executeScripts();
        // Test hook shared with the C / Go / Rust runners: KUI_EXAMPLE_DEVTOOLS_PORT=<port> starts
        // DevTools so scripts/verify_example_ports.py can click and read the DOM.
        const std::string port = tour_env("KUI_EXAMPLE_DEVTOOLS_PORT");
        if (!port.empty()) window->startDevTools(static_cast<kui::u16>(std::atoi(port.c_str())));
        tour_ready(*window, *document);
        const int code = kui::Platform::run();
        tour_script = nullptr;
        return code;
    } catch (const std::exception& error) {
        std::fprintf(stderr, "[kui_api_events] %s\n", error.what());
        return 9;
    }
}
